void sub_0208BAD8(PokemonSummary *summaryScreen, u8 *moveIndex, s16 *outX, s16 *outY);

void sub_0208BAD8(PokemonSummary *summaryScreen, u8 *moveIndex, s16 *outX, s16 *outY) {
    s16 newYPos = 16 + *moveIndex * 32;

    for (s16 i = 0; i < 4; i++) {
        Sprite_GetPositionXY(summaryScreen->sprites[SUMMARY_MOVE_TYPE_ICON_SPRITE_START + i], outX, outY);

        if (newYPos == *outY) {
            *moveIndex = i;
            break;
        }
    }
}
